(function(root){
'use strict';
const C=root.FourYearsContent,E=root.FourYearsEngine,S=root.FourYearsStorage,B=root.FourYears,A=root.FourYearsArt,config=root.FOUR_YEARS_CONFIG;
const $=s=>document.querySelector(s),app=$('#app'),dialog=$('#game-dialog'),toastEl=$('#toast');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number(n||0).toLocaleString('zh-CN',{maximumFractionDigits:1});
const fmtDelta=n=>(n>0?'+':'')+num(n);
const byId=(xs,id)=>xs.find(x=>x.id===id);
const icon=A.icon,routeName=id=>byId(C.ROUTES,id)?.name||id;
let state=null,view='actions',category='recommend',target='lin',routeTab='routes',journalTab='memories',modalLocked=false,toastTimer=null,sound=false,audio=null,disposed=false;
let leaderboardSource='local',leaderboardRows=[],leaderboardSchool='',leaderboardError='',networkBusy=false,lastPlan=[],activeDialog='';
let setup={name:'上大小新',school:'shu',difficulty:'balanced',family:'ordinary',gender:'male',romance:'women',focus:'balanced',campusMode:'shu',homeCampus:'baoshan',major:'general',talents:['curious','listener'],seed:''};
const slogans=[['新的故事，从这里开始','把陌生的路走熟，把喜欢的事慢慢找到。'],['在岔路口，长出自己的方向','不必同时成为所有人。认真做完一件事，也很好。'],['想去的地方，开始变得具体','那些微小的积累，正在长成选择未来的底气。'],['毕业不是终点，是下一页','把重要的人放在心里，把没有做完的梦带走。']];
let shuChapter=0;
let mapArea='all',locationFilter='',actionSearch='',skillFilter='all';
const areaNames={baoshan:'宝山生活圈',yanchang:'延长生活圈',jiading:'嘉定生活圈',city:'城市与社区'};
function systemBanner(){const p=E.academicPeriod(state),sk=state.skills,course=byId(C.COURSES,state.curriculum.active);return `<div class="systems-ribbon"><button data-action="tab" data-id="shu">${icon('leaf')}<span>上大手帐 ${state.shu.completed.length}/${C.SHU_TASKS.length}<small>${E.campusAgenda(state).title}</small></span></button><button data-action="tab" data-id="campuslife">${icon('book')}<span>${p.name}<small>${course?`${course.name} · ${state.curriculum.progress}/4`:p.summer?'夏季实践，把积累用起来':'选课、社团、宿舍与经营'}</small></span></button><button data-action="tab" data-id="skills">${icon('brain')}<span>${sk.points} 个技能点<small>已装备 ${sk.equipped.length}/3 · 搭配成长方式</small></span></button></div>`;}
function mapView(){const places=C.LOCATIONS.filter(l=>mapArea==='all'||l.campus===mapArea);return `<div class="content-heading"><div><span class="kicker">ONE SHU / CONNECTED PLACES</span><h3>同一个上大，不同的生活半径</h3><p>${C.LOCATIONS.length}个可行动地点。宝山、延长、嘉定属于同一校园篇章；校外实践也从这里出发。</p></div><span class="tag">足迹 ${state.campus.visited.length}/${C.LOCATIONS.length}</span></div><div class="filters">${[['all','全部生活圈'],...Object.entries(areaNames)].map(([id,n])=>`<button class="filter ${mapArea===id?'active':''}" data-action="map-area" data-id="${id}">${n}</button>`).join('')}</div><section class="shu-map panel" aria-label="上大校区与行动地点关系示意"><div class="row between"><div><span class="kicker">CAMPUS CONNECTIONS</span><h3>先约好要做的事，再决定去哪里</h3></div>${icon('compass')}</div><div class="shu-map-regions">${Object.entries(areaNames).filter(([id])=>mapArea==='all'||mapArea===id).map(([id,name])=>`<section class="shu-map-region"><h4>${name}</h4><p>${id==='baoshan'?'阅读、课堂、科研与共同生活':id==='yanchang'?'资料、影像与设计实践':id==='jiading'?'语言、交流与人文观察':'从校园走向城市、社区与更远的生活'}</p><div class="shu-map-links">${places.filter(l=>l.campus===id).map(l=>`<button class="map-place-button ${state.campus.visited.includes(l.id)?'visited':''}" data-action="map-place" data-id="${l.id}">${icon(l.icon,'sm')}${l.name}${state.campus.visited.includes(l.id)?'<span aria-label="已到访">✓</span>':''}</button>`).join('')}</div></section>`).join('')}</div><p class="quick-help">这是地点与玩法的关系示意，不是按比例地图。点击地点不会产生足迹；实际完成行动才会记录。跨圈压力按当月行动顺序计算。</p></section><div class="location-grid">${places.map(l=>`<article class="location-card panel"><div class="row between"><span class="tag neutral">${areaNames[l.campus]}</span><span class="visited-label">${state.shu.locationCounts[l.id]||0}次实际行动</span></div><h4>${icon(l.icon)}${l.name}</h4><p>${l.text}</p><div class="location-actions">${l.actions.map(id=>`<button data-action="add" data-id="${id}" title="${esc(E.actionReason(state,id,E.actions[id].target?target:undefined)||'加入本月')}" ${E.actionReason(state,id,E.actions[id].target?target:undefined)?'disabled':''}>${icon('plus','sm')}${E.actions[id].name}</button>`).join('')}</div><button class="btn compact ghost" data-action="map-place" data-id="${l.id}">查看行动收益 ${icon('arrow','sm')}</button></article>`).join('')}</div><p class="quick-help">真实馆名、校区与文化背景有出处；其余课堂、社团与实践空间是上大生活的功能化表示。<button class="text-link" data-action="sources">查看资料</button></p>`;}
function skillsView(){const branches=[...new Set(C.SKILL_NODES.map(n=>n.branch))],sk=state.skills;return `<div class="content-heading"><div><span class="kicker">BUILD YOUR OWN WAY</span><h3>不是全都会，而是搭配出自己的长处</h3><p>20个分支、40个可学习技能；每3个月获得1点，最多装备3项。同分支仅最高级生效。</p></div><span class="skill-points">${sk.points}<small>可用点数</small></span></div><div class="skill-loadout panel">${[0,1,2].map(i=>{const n=byId(C.SKILL_NODES,sk.equipped[i]);return `<div class="loadout-slot ${n?'equipped':''}">${icon(n?.icon||'plus')}<span>${n?n.name:'空技能槽'}<small>${n?'对应行动能力 +'+Math.round(n.boost*100)+'%':'学会后点击装备'}</small></span>${n?`<button class="icon-button" data-action="equip-skill" data-id="${n.id}" aria-label="卸下${n.name}">${icon('cross')}</button>`:''}</div>`;}).join('')}</div><div class="skill-tree">${branches.map(branch=>{const nodes=C.SKILL_NODES.filter(n=>n.branch===branch);return `<section class="skill-branch panel"><div class="row between"><h4>${icon(nodes[0].icon)}${nodes[0].branchName}</h4><span class="tiny muted">${C.STATS[nodes[0].stat][0]} ${num(state.stats[nodes[0].stat])}</span></div>${nodes.map(n=>{const learned=sk.unlocked.includes(n.id),equipped=sk.equipped.includes(n.id),reason=E.skillReason(state,n.id);return `<article class="skill-node ${learned?'learned':''} ${equipped?'active':''}"><div class="row between"><b>${n.name}</b><span class="tag ${n.level===2?'gold':''}">+${Math.round(n.boost*100)}%</span></div><p>${n.text}</p><div class="row between"><span class="tiny muted">${n.level===2?'进阶 · ':'基础 · '}${n.cost}点 / ${C.STATS[n.stat][0]} ${n.req}</span>${learned?`<button class="btn compact ${equipped?'soft':''}" data-action="equip-skill" data-id="${n.id}">${equipped?'卸下':'装备'}</button>`:`<button class="btn compact" data-action="unlock-skill" data-id="${n.id}" title="${esc(reason||'学习技能')}" ${reason?'disabled':''}>${reason?'尚未满足':'学习'}</button>`}</div>${reason&&!learned?`<div class="tiny muted skill-reason">${esc(reason)}</div>`:''}</article>`;}).join('<div class="skill-connector">↓</div>')}</section>`;}).join('')}</div>`;}
function campusLifeView(){const p=E.academicPeriod(state),course=byId(C.COURSES,state.curriculum.active),club=byId(C.CLUBS,state.club.id),v=state.venture,forecast=E.ventureForecast(state);return `<div class="content-heading"><div><span class="kicker">A LIFE THAT FITS TOGETHER</span><h3>课表、室友、社团，和正在起步的小事业</h3><p>这些选择不占行动时段，但收益必须通过真实行动与月度结算取得。</p></div></div><div class="systems-grid"><section class="system-card panel"><div class="system-head"><span class="system-symbol">${icon('book')}</span><div><h3>${p.name} · 专题选课</h3><p>每个长学期一门，完成4次匹配行动结课。</p></div></div>${course?`<div class="notice green">${course.name} · 已完成 ${state.curriculum.progress}/4 次实践<div class="progress"><span style="width:${state.curriculum.progress/4*100}%"></span></div></div>`:p.summer?'<div class="notice">夏季实践期：实践行动及项目成长 +15%；新学期开放下一次选课。</div>':`<div class="course-grid">${C.COURSES.map(c=>`<button class="course-option" data-action="select-course" data-id="${c.id}"><b>${c.name}</b><span>${c.text}</span><small>${Object.entries(c.reward).map(([k,n])=>C.STATS[k][0]+' +'+n).join(' / ')}</small></button>`).join('')}</div>`}<p class="quick-help">已结课 ${state.curriculum.records.filter(c=>c.completed).length} 门。选课只是确定方向，反复点击不会发放奖励。学期时点为48月玩法抽象。</p></section><section class="system-card panel"><div class="system-head"><span class="system-symbol">${icon('flag')}</span><div><h3>我的长期社团</h3><p>贡献6 / 16 / 30次，相关行动获得3% / 6% / 9%成长加成。</p></div></div>${club?`<div class="notice green">${club.name} · 贡献 ${state.club.memberships[club.id].contribution} · 等级 ${state.club.memberships[club.id].level}</div>`:''}<div class="club-grid">${C.CLUBS.map(c=>`<button class="club-option ${state.club.id===c.id?'active':''}" data-action="join-club" data-id="${c.id}" ${state.club.id===c.id?'disabled':''}><strong>${c.name}</strong><span>${c.text||'持续完成匹配活动，积累贡献与协作能力。'}</span></button>`).join('')}</div><p class="quick-help">切换至少间隔3个月；贡献按社团分别保留，不会重复发放等级奖励。</p></section><section class="system-card panel"><div class="system-head"><span class="system-symbol">${icon('home')}</span><div><h3>宿舍是共享的生活</h3><p>熬夜影响氛围；室友沟通、休息和照顾生活有助于修复。</p></div></div><div class="dorm-meter"><strong>${num(state.dorm.harmony)}<small> /100 氛围</small></strong><div class="progress"><span style="width:${state.dorm.harmony}%"></span></div></div><div class="pact-options">${[['balanced','互相照顾','均衡安排，留出彼此空间。'],['quiet','安静时段','氛围≥45时，学习行动成长 +5%。'],['creative','创作默契','氛围≥45时，创作行动成长 +5%。']].map(([id,name,text])=>`<button class="pact-option ${state.dorm.pact===id?'active':''}" data-action="dorm-pact" data-id="${id}"><strong>${name}</strong><span>${text}</span></button>`).join('')}</div><button class="btn compact" data-action="add" data-id="roommeeting">${icon('chat')}安排一次室友沟通</button><p class="quick-help">氛围≥75每月减压；低于30会增加压力。约定不代表任何真实宿舍管理规定。</p></section><section class="system-card panel"><div class="system-head"><span class="system-symbol">${icon('briefcase')}</span><div><h3>小事业 · 现金流</h3><p>完成产品后再营业；不是点击一次“创业成功”。</p></div></div><div class="venture-numbers"><div><strong>${num(v.customers)}</strong><small>留存客户</small></div><div><strong>¥${num(v.net)}</strong><small>上月经营净额</small></div><div><strong>${v.profitableMonths}</strong><small>盈利月份</small></div></div><div class="pact-options">${[['off','暂停营业','无运营支出'],['lean','精益经营','每月运营 ¥300'],['growth','扩大投入','每月运营 ¥900']].map(([id,name,text])=>`<button class="pact-option ${v.mode===id?'active':''}" data-action="venture-mode" data-id="${id}" ${!forecast.eligible&&id!=='off'?'disabled':''}><strong>${name}</strong><span>${text}</span></button>`).join('')}</div>${!forecast.eligible?'<div class="notice">需完成产品或社会企业项目，并达到经营30，才能开始营业。</div>':`<p class="quick-help">本模式运营支出 ¥${forecast.cost}/月。每月实际安排经营活动才能获客；忽略客户会流失。扣费后不足¥800生活储备时自动暂停，不会自动借款。</p>`}<div class="venture-ledger">${v.records.length?`<table><thead><tr><th>月份</th><th>营收</th><th>运营</th><th>净额</th></tr></thead><tbody>${v.records.slice(-5).reverse().map(r=>`<tr><td>${r.month}</td><td>${num(r.revenue)}</td><td>${num(r.cost)}</td><td>${fmtDelta(r.net)}</td></tr>`).join('')}</tbody></table>`:'<p class="small muted">经营后会在这里留下最近五个月的收支。</p>'}</div></section></div>`;}
function collaboratorPanel(){const eligible=C.NPCS.filter(n=>state.relations[n.id].known&&state.relations[n.id].trust>=20);return `<section class="collaborator-panel panel"><div class="row between"><div><h4>${icon('chat')}把关系变成真实合作</h4><p>信任≥20的朋友可以协助项目；匹配专长会更有效，完成后留下共同回忆。</p></div><span class="tag">${state.collaborator?E.npcs[state.collaborator].name:'当前独立完成'}</span></div><select aria-label="项目合作伙伴" data-action-select="collaborator"><option value="none">这次独立完成</option>${eligible.map(n=>`<option value="${n.id}" ${state.collaborator===n.id?'selected':''}>${n.name} · ${C.STATS[n.affinity][0]}方向 / 信任${num(state.relations[n.id].trust)}</option>`).join('')}</select>${!eligible.length?'<p class="tiny muted">先在人物页聊天或共同活动，积累信任。友情也能形成有价值的成果。</p>':''}</section>`;}
function showSources(){showModal('上海大学校园篇 · 资料与改编边界',`<p>本作不是上海大学官方游戏，也未获其授权或背书。${C.NPCS.length}位人物、社团活动、专题课程、项目与事件均为虚构游戏内容；没有使用真实学生或教师作为恋爱角色。</p><div class="notice" style="margin:16px 0">采用公开资料中的“两长一短”学期结构作为灵感；具体月份、能力加成、学制与升学门槛都是游戏规则。三生活圈地图不按比例，也不提供真实出入校或导航指引。</div><div class="source-list">${C.SOURCES.map(s=>`<article><h4>${s.title}</h4><p>${s.fact}</p><small class="muted">游戏改编：${s.adaptation}</small><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">打开校方公开资料 ↗</a></article>`).join('')}</div><p class="small muted">核对日期：2026-09-12。历史活动仅作内容灵感，不代表2026年活动安排。游戏本体无外部字体、图片、统计脚本或自动联网请求。</p><button class="btn full" data-action="close-modal">回到我的四年</button>`);}

function shuView(){
 const year=E.dateInfo(state).year,ch=shuChapter||year,chapter=byId(C.SHU_CHAPTERS,ch),tasks=E.campusTaskStatus(state),agenda=E.campusAgenda(state);
 return `<div class="content-heading"><div><span class="kicker">YOUR SHU FIELDNOTES</span><h3>所有选择，写在同一本上大手帐里</h3><p>四个年度篇章，十二份投入证据。旧行动、新内容、课程、作品与关系，都能推进这些任务。</p></div><span class="tag gold">${state.shu.completed.length}/${C.SHU_TASKS.length} 页已完成</span></div><section class="shu-agenda panel"><div><span class="kicker">${E.dateInfo(state).month}月 · 校园活动提示</span><h3>${agenda.title}</h3><p>本月安排一项相关行动，可触发额外校园事件；每月最多一次，不需要另付行动时段。</p><small class="muted">${agenda.note}</small></div><span class="tag ${agenda.participated?'gold':agenda.planned?'':'neutral'}">${agenda.participated?'本月已参与':agenda.planned?'已安排相关行动':'按自己的兴趣参与'}</span><div class="shu-agenda-actions">${agenda.possibleActions.map(a=>{const reason=E.actionReason(state,a.id);return `<button class="btn compact soft" data-action="add" data-id="${a.id}" ${reason?'disabled':''} title="${esc(reason||'加入本月')}">${icon('plus','sm')}${a.name}</button>`;}).join('')}</div></section><div class="shu-chapter-tabs" aria-label="四年篇章">${C.SHU_CHAPTERS.map(c=>`<button class="${ch===c.id?'active':''}" data-action="shu-chapter" data-id="${c.id}"><small>第${c.id}年 ${c.id>year?'· 尚未到达':''}</small><strong>${c.name}</strong><span>${tasks.filter(t=>t.chapter===c.id&&t.completed).length}/3 页</span></button>`).join('')}</div><div class="shu-chapter-intro"><h3>${chapter.name}</h3><p>${chapter.text}</p><span class="tiny muted">条件可提前积累；到对应学年后结算。不会过期，不需要为了任务重开一局。</span></div><div class="shu-task-grid">${tasks.filter(t=>t.chapter===ch).map(t=>{const suggestions=[...new Set(t.goals.filter(g=>g.kind==='counts'&&g.value<g.target).flatMap(g=>g.ids))].slice(0,3);return `<article class="shu-task panel ${t.completed?'completed':''}"><div class="row between"><span class="tag ${t.completed?'gold':t.unlocked?'':'neutral'}">${t.completed?'第'+t.completedMonth+'月完成':t.unlocked?'正在书写':'第'+t.chapter+'年开启'}</span>${icon(t.completed?'medal':'book')}</div><h3>${t.name}</h3><p>${t.text}</p><ul class="shu-goals">${t.goals.map(g=>`<li class="${g.value>=g.target?'done':''}"><span>${g.value>=g.target?'✓':'○'} ${g.label}</span><strong>${num(g.value)}/${g.target}</strong></li>`).join('')}</ul><div class="progress"><span style="width:${t.completed?100:t.progress}%"></span></div><div class="shu-reward">完成奖励：${Object.entries(t.reward).map(([k,v])=>C.STATS[k][0]+' +'+v).join(' · ')}${t.money?' · 游戏内支持 ¥'+t.money:''}</div>${!t.completed?`<div class="shu-task-links">${suggestions.map(id=>`<button class="text-link" data-action="add" data-id="${id}" ${E.actionReason(state,id,E.actions[id].target?target:undefined)?'disabled':''}>${icon('plus','sm')}${E.actions[id].name}</button>`).join('')}</div>`:'<p class="tiny muted">已记录，奖励不会重复领取。</p>'}</article>`;}).join('')}</div><section class="shu-archive panel"><div class="row between"><h3>参加过的校园活动</h3><span class="tag neutral">${state.shu.agenda.length} 次</span></div>${state.shu.agenda.length?`<div class="shu-stamps">${state.shu.agenda.slice(-12).reverse().map(a=>`<span><small>第${a.year}年 · ${((a.month+7)%12)+1}月</small>${byId(C.SHU_AGENDA,a.id).title}</span>`).join('')}</div>`:'<p>没有空降的成就。参与本月相关行动后，故事会从这里开始。</p>'}</section>`;
}

function toast(text){clearTimeout(toastTimer);toastEl.textContent=text;toastEl.classList.add('visible');toastTimer=setTimeout(()=>toastEl.classList.remove('visible'),3200);}
function chime(type='click'){if(!sound)return;try{audio=audio||new (root.AudioContext||root.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=type==='end'?660:440;o.connect(g);g.connect(audio.destination);g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.15);o.start();o.stop(audio.currentTime+.16);}catch(e){sound=false;}}
function status(){return S.status().durable?'本地自动存档':'仅内存 · 请导出';}
function save(slot='auto'){if(!state)return null;const result=S.save(state,slot);if(!result.durable)toast(result.error);B._emit('save',{slot,month:state.month,durable:result.durable});return result;}
function replaceState(s){state=s;view='actions';category='recommend';target=state.partner||Object.keys(state.relations).find(id=>state.relations[id].known&&E.romanceAllowed(state,id))||'lin';lastPlan=E.clone(state.reports.at(-1)?.plan||[]);closeModal(true);save();if(state.phase==='ended')S.recordResult(state.result);render();}
function load(slot='auto'){try{const s=S.load(slot);if(!s){toast('这个存档位还是空的。');return;}replaceState(s);toast(`已回到第${s.month}个月。`);}catch(e){toast(e.message);}}
function afterChange(previousPhase,options={}){
  state.updatedAt=new Date().toISOString();save();
  B._emit('state:change',{month:state.month,phase:state.phase,revision:state.revision});
  if(previousPhase==='events'&&['report','ended'].includes(state.phase)){B._emit('month:end',state.reports.at(-1));if(config.autoSync&&B.connected())B.syncProgress().catch(e=>toast(e.message));}
  if(state.phase==='ended'&&previousPhase!=='ended'){S.recordResult(state.result);B._emit('run:end',state.result);chime('end');}
  if(options.render!==false)render();
}
function applyEngine(fn){if(!state)return;const oldPhase=state.phase;try{const out=fn();if(out&&!out.ok){toast(out.reason);return false;}afterChange(oldPhase);return true;}catch(e){console.error(e);toast('操作没有完成：'+e.message);B._emit('error',{message:e.message});return false;}}
function beginRun(){
  if(setup.talents.length!==2){toast('请选择两项入学天赋。');return;}
  const start=()=>{state=E.createGame({...setup,seed:setup.seed.trim()||('上大-'+Date.now().toString(36))});view='actions';category='recommend';target=state.profile.romance==='men'?'gu':'lin';lastPlan=[];closeModal(true);save();B._emit('run:start',{runId:state.runId,profile:state.profile,seed:state.seed});render();chime();root.scrollTo({top:0,behavior:'instant'});};
  const auto=S.slots().find(x=>x.id==='auto');if(auto?.exists&&auto.phase!=='ended')confirmBox('开始新的四年？','新开局会替换自动存档。手动存档、已解锁图鉴和本机排行榜不会被清除。','开始新故事',start);else start();
}
function header(){return `<header class="topbar"><button class="brand" data-action="home" aria-label="返回游戏首页"><span class="brand-mark">${icon('leaf')}</span><span><span class="brand-title">${esc(config.title)}</span><span class="brand-en" style="display:block">FOUR YEARS, YOURS.</span></span></button><div class="top-actions"><span class="offline-badge"><span class="dot"></span> ${esc(B.connected()?'单机运行 · 可选同步':'纯单机 · 无需联网')}</span>${state?`<button class="btn ghost mobile-stats-btn" data-action="stats" title="查看全部属性" aria-label="查看全部属性">${icon('brain')}</button>`:''}<button class="btn ghost" data-action="help" title="玩法说明" aria-label="玩法说明">${icon('info')}<span class="button-label">玩法</span></button><button class="btn ghost" data-action="book" title="结局图鉴" aria-label="结局图鉴">${icon('book')}<span class="button-label">图鉴</span></button><button class="btn ghost" data-action="leaderboard" title="排行榜" aria-label="排行榜">${icon('trophy')}<span class="button-label">榜单</span></button><button class="btn" data-action="saves" title="存档管理" aria-label="存档管理">${icon('save')}<span class="button-label">存档</span></button></div></header>`;}
function footer(){return `<footer class="footer"><span>上海大学公开文化灵感 × 虚构成年人物 · 非官方作品 · 学制、考试、地图为游戏抽象</span><span>${esc(config.version)} · ${C.ACTIONS.length}项行动 / ${C.ENDINGS.length}种结局 · <button data-action="sound" style="padding:0;font-size:inherit;color:inherit">音效${sound?'开':'关'}</button></span></footer>`;}
function renderStart(){
 const auto=S.slots().find(x=>x.id==='auto'),d=byId(C.DIFFICULTIES,setup.difficulty),book=S.collection();
 app.innerHTML=header()+`<main class="welcome"><section class="welcome-hero"><div class="hero-overline"><span class="kicker">SHANGHAI UNIVERSITY / 3.0 · 同一校园，所有可能</span></div><h1 class="welcome-title">此刻，上大。<br>四年，<em>一起写完。</em></h1><p class="welcome-copy">宝山的阅读灯，延长的创作页，嘉定的相遇。<br>所有学习、恋爱、创业与探索，都在同一段四年里。<br>不必活成标准答案，但可以把一件事认真做完。</p><div class="welcome-stats"><div><strong>48</strong><span>个月的共同生活</span></div><div><strong>${C.ROUTES.length}</strong><span>条相互连接的路</span></div><div><strong>${C.ENDINGS.length}</strong><span>种毕业与人生结局</span></div></div>${A.campus('autumn',true)}<div class="shu-welcome-note"><span class="kicker">ONE UNIVERSITY. MANY WAYS TO GROW.</span><h3>不再切换校园篇章</h3><p>阅读可以连接科研，也可以遇见朋友；朋友可以协助作品；作品可以成为升学、求职或创业的起点。四张年度手帐，把这些变化连在一起。</p><div class="shu-mini-chapters">${C.SHU_CHAPTERS.map(c=>`<span><small>0${c.id}</small>${c.name}</span>`).join('')}</div></div><p class="hero-quote">“把陌生走成熟悉，把喜欢做成自己的事。”</p></section><section class="admission panel"><div class="admission-top row between"><div><div class="kicker">YOUR LIFE AT SHU</div><h2>你的上大入学档案</h2><p class="small muted">唯一校园：上海大学 · 非官方生活模拟</p></div><span class="stamp">上大<br>四年留念</span></div>${auto?.exists?`<div class="continue-card row between"><div><strong>${esc(auto.name)}的故事 · 第${auto.month}月</strong><span class="tiny muted">本版本独立存档，不覆盖旧版记录</span></div><button class="btn compact" data-action="continue">继续 ${icon('arrow','sm')}</button></div>`:''}<div class="form-grid"><label><span class="field-label">同学，怎么称呼你？</span><input id="player-name" name="name" maxlength="16" value="${esc(setup.name)}" autocomplete="off" data-setup="name"></label><label><span class="field-label">家庭支持</span><select data-setup="family">${C.FAMILIES.map(f=>`<option value="${f.id}" ${setup.family===f.id?'selected':''}>${f.name} · ¥${f.stipend}/月</option>`).join('')}</select></label></div><div class="form-section"><span class="field-label">选择个人挑战 <span class="tiny muted">只改变游戏数值，不改变学校</span></span><div class="school-grid" role="group" aria-label="个人挑战难度">${C.DIFFICULTIES.map(x=>`<button class="school-card ${setup.difficulty===x.id?'active':''}" data-action="difficulty" data-id="${x.id}" aria-pressed="${setup.difficulty===x.id}"><strong>${x.name}</strong><small>${x.tag}</small></button>`).join('')}</div><p class="school-detail">${d.text}<span>挑战系数 ×${d.multiplier.toFixed(2)}</span></p></div><div class="campus-setup form-section"><span class="field-label">起居与兴趣 · 在同一个上大世界里</span><div class="form-grid"><label><span class="tiny muted">常住校区生活圈</span><select aria-label="常住生活圈" data-setup="homeCampus">${C.HOME_CAMPUSES.map(c=>`<option value="${c.id}" ${setup.homeCampus===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label><label><span class="tiny muted">初始专业兴趣</span><select aria-label="初始专业兴趣" data-setup="major">${C.MAJORS.map(c=>`<option value="${c.id}" ${setup.major===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label></div><p class="tiny muted" style="margin-top:8px">校区、馆名与文化背景参考公开资料；住宿分配、兴趣课程和通勤数值为游戏抽象。<button class="text-link" data-action="sources">查看出处与改编边界</button></p></div><div class="form-grid"><label><span class="field-label">角色性别</span><select data-setup="gender">${[['male','男生'],['female','女生'],['other','自定义／不标注']].map(([id,label])=>`<option value="${id}" ${setup.gender===id?'selected':''}>${label}</option>`).join('')}</select></label><label><span class="field-label">恋爱偏好</span><select data-setup="romance">${[['women','偏好女生'],['men','偏好男生'],['all','都可以遇见'],['none','专注友情与自己']].map(([id,l])=>`<option value="${id}" ${setup.romance===id?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="form-section"><span class="field-label">带上两项天赋 <span>${setup.talents.length}/2</span></span><div class="talent-grid">${C.TALENTS.slice(0,6).map(t=>talentChip(t)).join('')}</div><details class="talent-detail"><summary>更多天赋与挑战种子</summary><div class="talent-grid" style="margin-top:9px">${C.TALENTS.slice(6).map(t=>talentChip(t)).join('')}</div><label class="seed-row"><span class="field-label">相同种子＋相同选择，可以复现这段人生</span><input data-setup="seed" maxlength="80" value="${esc(setup.seed)}" placeholder="留空生成本地种子"></label></details></div><label><span class="field-label">先朝哪个方向试试看？</span><select data-setup="focus">${C.ROUTES.map(r=>`<option value="${r.id}" ${setup.focus===r.id?'selected':''}>${r.name}</option>`).join('')}</select></label><button class="btn primary full start-button" id="start-game" data-action="start">从上海大学，开始我的四年 ${icon('arrow')}</button><p class="admission-note">每月4个行动时段。12项上大篇章任务记录真实投入，自动结算奖励；不必全部完成，也不强迫选择某一种人生。人物均为虚构成年人。</p>${book.runs?`<p class="admission-note">已完成 ${book.runs}段故事 · 图鉴 ${Object.keys(book.endings).length}/${C.ENDINGS.length} · 本机最高 ${num(book.best)}</p>`:''}</section></main>`+footer();
}
function talentChip(t){return `<button class="talent-chip ${setup.talents.includes(t.id)?'active':''}" data-action="talent" data-id="${t.id}" aria-pressed="${setup.talents.includes(t.id)}" title="${esc(t.text)}">${icon(t.icon)}<span>${t.name}<small>${t.text}</small></span></button>`;}
function statRow(k,s=state){const [name,ico,desc]=C.STATS[k],value=s.stats[k];return `<div class="stat-item" title="${esc(desc)}"><div class="row"><span class="stat-label">${icon(ico)}${name}</span><strong>${num(value)}</strong></div><div class="progress ${k==='stress'?'rose':k==='charm'?'gold':''}"><span style="width:${value}%"></span></div></div>`;}
function academic(){const avg=E.gradeAverage(state);return `<div class="academic-grid"><div class="academic-cell"><small>${state.grades.length?'累计学期均分':'学期均分预估'}</small><strong class="academic-value">${num(avg)}</strong></div><div class="academic-cell"><small>备考综合值</small><strong class="academic-value">${num(E.examReadiness(state))}</strong></div></div><div class="academic-flags">${state.failedCourses?`待补课程：${state.failedCourses}门`:'课程状态：正常'}<br>毕业设计：${state.flags.thesis?'已完成':state.month>=37?'尚未完成 · 请安排项目':'第37月开放'}<br>${state.admission?`升学：已接受${{baoyan:'推免',kaoyan:'考研',overseas:'海外'}[state.admission.path]}录取`:'升学录取：尚未确认'}</div>`;}
function sidebar(){const sc=byId(C.SCHOOLS,state.profile.school),f=byId(C.FAMILIES,state.profile.family),route=byId(C.ROUTES,state.focus),scores=E.routeScores(state);return `<aside class="sidebar"><div class="panel profile-panel"><div class="profile-head"><div class="player-avatar">${icon(state.profile.gender==='female'?'spark':'leaf')}</div><div><h2 class="profile-name">${esc(state.profile.name)}</h2><div class="profile-school">上海大学 · ${E.difficulty(state).name}</div></div></div><div class="stats-grid">${['iq','eq','charm','health','mood','stress','discipline'].map(k=>statRow(k)).join('')}</div><div class="profile-finance"><div class="row between"><span class="tiny muted">我的小金库</span>${icon('wallet','sm')}</div><div class="finance-main">¥${num(state.money)}</div><div class="tiny muted">每月支持 ¥${f.stipend} · 基础开销 ¥800</div></div></div><section class="focus-panel"><label class="field-label" for="focus-select">本阶段想试试的方向 ${icon(route.icon,'sm')}</label><select id="focus-select" data-action-select="focus" ${state.phase!=='planning'?'disabled':''}>${C.ROUTES.map(r=>`<option value="${r.id}" ${state.focus===r.id?'selected':''}>${r.name}</option>`).join('')}</select><div class="focus-score">${num(scores[state.focus])}<small>/ 100</small></div><p class="focus-guide">${route.guide}</p><div class="progress"><span style="width:${scores[state.focus]}%"></span></div><p class="tiny muted" style="margin-top:7px;font-size:8px">方向成熟度，不等于录取／成功概率</p></section><section class="panel profile-academic">${academic()}</section></aside>`;}
function nextDeadline(){const m=state.month;const notices=[[state.profile.campusMode==='shu'?5:6,'长学期末结算成绩','必修学习自动进行；专题选课需实际完成4次匹配行动。'],[13,'实习与跨专业补强开放','技能25可见习，也可开始跨专业基础补强。'],[24,'四年过半，路线可以调整','完成一件长期项目，会比一直增加属性更接近高分。'],[36,'第36月：推免夏令营','需要相应均分、科研55、完成论文、无待补课程。'],[37,'第37月：毕业设计开放','所有路线都需要完成毕业设计，别把它留到最后。'],[38,'第38月：考研报名','先完成衔接资格；接受推免后不再重复报名。'],[39,'第39月：申请窗口','秋招、公共岗位与海外申请，会逐项询问。'],[40,'第40月：考研初试','备考之外，健康和压力会影响临场发挥。'],[43,'第43月：考研复试','表达、语言与研究准备也会进入综合评价。'],[44,'第44月：申请结果','公共岗位与海外申请结果公布。'],[48,'第48月：毕业结算','请确认毕业设计已完成、课程没有待补项。']];return notices.find(x=>x[0]>=m)||notices.at(-1);}
function semesterStrip(){const d=E.dateInfo(state);return `<div class="semester-strip"><div class="month-title serif">${d.label}<span>第 ${String(state.month).padStart(2,'0')} / 48 个月</span></div><div class="year-timeline">${[1,2,3,4].map(y=>{const progress=E.clamp((state.month-(y-1)*12-1)/12*100);return `<div class="year-segment ${d.year===y?'active':''}"><div class="row"><span>${['初见','探索','选择','启程'][y-1]}</span><span>YEAR ${y}</span></div><div class="progress"><span style="width:${progress}%"></span></div></div>`;}).join('')}</div><button class="icon-button mobile-stats-btn" data-action="stats" title="人物与方向" aria-label="人物与方向">${icon('brain')}</button></div>`;}
function renderGame(){const d=E.dateInfo(state),slogan=slogans[d.year-1];app.innerHTML=header()+`<main class="game-shell">${semesterStrip()}<div class="play-layout">${sidebar()}<section class="main-column"><section class="campus-header panel"><div class="campus-copy"><span class="kicker">CHAPTER ${String(state.month).padStart(2,'0')} · ${['FIRST STEPS','FIND YOUR RHYTHM','MAKE YOUR CHOICE','A NEW BEGINNING'][d.year-1]}</span><h2>${slogan[0]}</h2><p>${slogan[1]}</p></div><div class="campus-weather">${icon({spring:'leaf',summer:'sun',autumn:'compass',winter:'cloud'}[d.season])}<span>${{spring:'春风正好，适合新的尝试',summer:'阳光很长，故事也很长',autumn:'风吹过树梢，新的一页展开',winter:'天气微凉，也要照顾好自己'}[d.season]}</span></div>${A.campus(d.season)}</section>${systemBanner()}${state.recovery?'<div class="notice rose" style="margin-top:12px">恢复月：健康或压力亮起提醒。四个时段中，至少安排两次休息、回家或慢跑。</div>':''}${state.month>=37&&!state.flags.thesis?'<div class="notice" style="margin-top:12px">毕业提醒：请在「长期项目」选择毕业设计，并安排项目行动完成。未完成会进入延毕结局。</div>':''}<nav class="main-tabs" aria-label="游戏页面">${[['actions','月度安排','clock'],['shu','上大手帐','leaf'],['map','校园地图','map'],['skills','技能树','brain'],['campuslife','校园生活','home'],['people','认识的人','heart'],['projects','长期项目','flag'],['routes','方向图鉴','compass'],['journal','成长手帐','book']].map(([id,label,ico])=>`<button data-action="tab" data-id="${id}" class="${view===id?'active':''}" aria-current="${view===id?'page':'false'}">${icon(ico)}${label}</button>`).join('')}</nav><div id="view-content">${renderView()}</div></section>${planner()}</div></main>`+footer();}
function renderView(){return view==='shu'?shuView():view==='map'?mapView():view==='skills'?skillsView():view==='campuslife'?campusLifeView():view==='people'?peopleView():view==='projects'?projectsView():view==='routes'?routesView():view==='journal'?journalView():actionsView();}
function actionGains(a){const entries=Object.entries(E.actionPreview(state,a.id).effects).filter(([k,v])=>v!==0).slice(0,5);return entries.map(([k,v])=>`<span class="gain ${v<0&&k!=='stress'?'neg':''}">${C.STATS[k][0]} ${fmtDelta(v)}</span>`).join('');}
function targetSelect(){return `<div class="relation-target"><span>${icon('heart','sm')} 互动对象 · 可在「认识的人」切换</span><select data-action-select="target" aria-label="互动对象">${C.NPCS.filter(n=>state.relations[n.id].known).map(n=>`<option value="${n.id}" ${target===n.id?'selected':''}>${n.name}${state.partner===n.id?' · 伴侣':''}</option>`).join('')}</select></div>`;}
function actionsView(){
 const route=byId(C.ROUTES,state.focus);let items;
 if(category==='recommend'){let ids=[...route.actions,'rest','run','lecture','parttime'];if(state.activeProject)ids.unshift('project');if(state.failedCourses)ids.unshift('remedial');items=[...new Set(ids)].map(id=>E.actions[id]).filter(Boolean);}else items=C.ACTIONS.filter(a=>category==='all'||a.cat===category);
 if(locationFilter)items=items.filter(a=>byId(C.LOCATIONS,locationFilter)?.actions.includes(a.id));
 if(actionSearch){const q=actionSearch.toLowerCase(),aliases={'摄影':'photography','拍照':'photography','智商':'iq','情商':'eq','外貌':'charm','编程':'tech','理财':'finance','口才':'negotiation','写作':'writing'};items=items.filter(a=>(a.name+a.desc+Object.keys(a.stats).map(k=>C.STATS[k].join(' ')).join('')).toLowerCase().includes(q)||(aliases[q]&&Object.hasOwn(a.stats,aliases[q]))||(['减压','放松'].includes(q)&&a.stats.stress<0)||(q==='赚钱'&&a.income>0));}
 return `<div class="content-heading"><div><h3>这个月，想做些什么？</h3><p>每项行动占1个时段。显示当前预计收益；技能、社团、季节、状态和同月重复会改变实际成长。</p></div><span class="tag neutral">${items.length}项行动</span></div><div class="action-search"><input type="search" aria-label="搜索行动或能力" data-action-select="search-action" placeholder="搜索行动、能力，例如：摄影、数据、减压" value="${esc(actionSearch)}"><button class="btn compact" data-action="search-actions">搜索</button>${locationFilter?`<button class="btn compact soft" data-action="clear-location">${byId(C.LOCATIONS,locationFilter).name} ×</button>`:''}</div><div class="filters">${[['recommend','按方向推荐','spark'],...C.CATEGORIES].map(([id,label,ico])=>`<button class="filter ${category===id?'active':''}" data-action="filter" data-id="${id}" aria-pressed="${category===id}">${icon(ico)}${label}</button>`).join('')}</div>${items.some(a=>a.target)?targetSelect():''}<div class="action-grid">${items.map(a=>actionCard(a)).join('')}</div>${!items.length?'<div class="empty">没有找到匹配的行动。换个词，或清空搜索再看看。</div>':''}<p class="quick-help">同月第二次相同行动的成长通常为65%（规划师80%）；压力和花费不会同比减少。尝试「图书馆＋跑步」「备考＋徒步」「训练＋复盘」等组合。</p>`;
}
function actionCard(a){const reason=E.actionReason(state,a.id,a.target?target:undefined),count=state.plan.filter(x=>x.id===a.id).length;const locked=reason&&!reason.includes('四个时段')&&!reason.includes('同一行动');const extra=a.id==='project'&&state.activeProject&&!state.projectStarts[state.activeProject]?E.projects[state.activeProject].cost:0;return `<article class="action-card ${locked?'locked':''}" data-testid="action-${a.id}"><div class="action-top"><span class="action-icon ${a.cat}">${icon(a.icon)}</span><div><h4>${a.name}${count?`<span class="action-count">×${count}</span>`:''}</h4></div></div><p>${a.desc}</p><div class="action-gains" title="按当前属性、天赋、技能和状态预估；同月后续属性变化会影响实际结果">${actionGains(a)}</div><div class="action-location">${icon('map','sm')}${E.actionPreview(state,a.id).location?.name||'自由安排'} · 能力系数 ×${E.actionPreview(state,a.id).multiplier}</div><div class="action-bottom"><div>${locked?`<div class="locked-reason">${esc(reason)}</div>`:`<span class="action-cost">${a.income?`收入 ¥${a.income}+`:a.cost?`花费 ¥${a.cost}`:'无需花费'}${extra?` · 首次另需¥${extra}`:''}</span>`}</div><button class="action-add" data-action="add" data-id="${a.id}" aria-label="安排${a.name}" title="${esc(reason||'加入本月安排')}" ${reason?'disabled':''}>${icon(locked?'lock':'plus')}</button></div></article>`;}
function planner(){const d=nextDeadline(),route=byId(C.ROUTES,state.focus),balance=E.availableMoney(state);return `<aside class="planner-column"><section class="planner panel"><div class="planner-top"><div class="row between"><h3>本月安排</h3><span class="planner-count">${state.plan.length}<small> / 4</small></span></div><div class="kicker">ONE MONTH, FOUR CHOICES.</div></div><div class="planner-body"><div class="plan-slots">${[0,1,2,3].map(i=>{const item=state.plan[i],a=item?E.actions[item.id]:null;return `<div class="plan-slot ${item?'filled':''}"><span class="slot-number">${i+1}</span>${item?`<div class="slot-content"><div class="slot-title">${a.name}</div><div class="slot-sub">${item.target?esc(E.npcs[item.target].name):a.id==='project'&&state.activeProject?E.projects[state.activeProject].name:a.income?'完成后获得收入':a.cost?`花费 ¥${a.cost}`:'为自己留下一点成长'}</div></div><div class="slot-tools"><button data-action="up" data-index="${i}" aria-label="上移第${i+1}项" title="上移">↑</button><button data-action="down" data-index="${i}" aria-label="下移第${i+1}项" title="下移">↓</button><button data-action="remove" data-index="${i}" aria-label="移除第${i+1}项" title="移除">${icon('cross')}</button></div>`:`<div class="slot-empty">留一点时间<br><span>给想做的事</span></div>`}</div>`;}).join('')}</div><div class="plan-controls"><button data-action="copy-plan" ${!lastPlan.length?'disabled':''}>${icon('clock')}沿用上月</button><button data-action="fill-plan">按目标补齐</button><button data-action="clear-plan">清空</button></div><div class="commute-preview"><span>${icon('map','sm')}跨生活圈 ${E.planPreview(state).crossings} 次</span><small>预计压力 +${E.planPreview(state).stress} · 顺序会影响通勤</small></div><div class="planner-bottom"><div><div class="planner-finance"><span>行动后预计余额</span><strong class="${balance<0?'error':''}">¥${num(balance)}</strong></div><p class="empty-plan-note">本月目标：${route.name}<br><span>${state.activeProject?`推进中：${E.projects[state.activeProject].name}`:'给长期目标留一点时间，也给休息留一点。'}</span></p></div><div><button class="btn primary full resolve-btn" id="resolve-month" data-action="resolve" ${state.plan.length<4?'disabled':''}>开始这个月 ${icon('arrow')}</button><p class="planner-footnote">完成行动 → 经历事件 → 翻到下个月<br>${esc(status())} · 第${state.month}月</p></div></div></div></section><div class="deadline notice"><h4>${icon('clock')}${d[1]}</h4><p>${d[2]}</p></div><p class="quick-help">保研不是每个人的必修课。每条成长路线都有自己的高分方法。<br>${state.profile.campusMode==='shu'?'秋、春长学期结算成绩，夏季专注实践':'每6个月结算学期成绩'}；选课、社团、技能与项目会互相影响。</p></aside>`;}
function peopleView(){return `<div class="content-heading"><div><h3>在人群中，遇见具体的你</h3><p>外貌影响初次心动，信任来自长期相处。友情同样有价值。</p></div><span class="tag rose">${Object.values(state.relations).filter(r=>r.known).length} / ${C.NPCS.length} 已相识</span></div>${state.partner?`<div class="notice green" style="margin-bottom:13px">正在与${E.npcs[state.partner].name}交往 · ${state.relations[state.partner].months}个月。关系需要沟通，也允许有边界。</div>`:''}<div class="npc-grid">${C.NPCS.map(n=>npcCard(n)).join('')}</div>`;}
function npcCard(n){const r=state.relations[n.id];if(!r.known)return `<article class="npc-card panel unknown"><div class="row"><span class="unknown-avatar">${icon(n.icon)}</span><div><h4 class="npc-title">${n.name}</h4><div class="npc-role">${n.role} · ${n.age}岁</div></div></div><p class="npc-hint">还没有相识。<br>可在${n.places.map(id=>E.actions[id]?.name).filter(Boolean).join('、')}中遇见${n.rich?'（第7月起）':''}。</p></article>`;
 const compatible=E.romanceAllowed(state,n.id),partner=state.partner===n.id;return `<article class="npc-card panel ${target===n.id?'selected':''}"><div class="row"><div>${A.portrait(n,55)}</div><div><h4 class="npc-title">${n.name} <span class="tiny muted">${n.age}岁</span></h4><div class="npc-role">${n.role}</div></div></div><p class="npc-intro">${n.intro}</p><div class="npc-bars"><div><div class="row between"><span>亲近度</span><span>${num(r.affection)}</span></div><div class="progress rose"><span style="width:${r.affection}%"></span></div></div><div><div class="row between"><span>信任</span><span>${num(r.trust)}</span></div><div class="progress"><span style="width:${r.trust}%"></span></div></div></div><div class="row wrap gap6" style="margin-top:11px"><span class="tag ${partner?'rose':'neutral'}">${partner?'我的恋人':r.trust>=55?'知心朋友':'慢慢熟悉'}</span><span class="tiny muted">故事 ${r.chapter}/3 · 回忆 ${r.memories}</span></div><div class="npc-buttons"><button class="btn compact" data-action="npc-add" data-id="listen" data-target="${n.id}">聊聊天</button>${compatible?`<button class="btn compact" data-action="npc-add" data-id="date" data-target="${n.id}">${partner?'约会':'邀请约会'}</button><button class="btn compact ${partner?'danger':'soft'}" data-action="${partner?'breakup-confirm':'npc-add'}" data-id="${partner?'breakup':'confess'}" data-target="${n.id}">${partner?'坦诚告别':'表达喜欢'}</button>`:''}<button class="btn compact" data-action="npc-detail" data-id="${n.id}">了解TA</button></div></article>`;}
function projectsView(){return `<div class="content-heading"><div><h3>把“有个想法”，变成“我做到了”</h3><p>先选项目，再安排「推进长期项目」。切换项目会保留已投入进度。</p></div><span class="tag gold">${Object.values(state.projectCompletions).reduce((a,b)=>a+b,0)} 项完成</span></div>${collaboratorPanel()}<div class="project-grid">${C.PROJECTS.map(p=>projectCard(p)).join('')}</div>`;}
function projectCard(p){const reason=E.projectReason(state,p.id),done=state.projectCompletions[p.id]||0,progress=state.projectProgress[p.id]||0,active=state.activeProject===p.id;return `<article class="project-card panel ${active?'active':''} ${done?'completed':''}"><div class="row gap6"><span class="action-icon career">${icon(p.icon)}</span><h4>${p.name}</h4></div><p>${p.text}</p><div class="row between small muted" style="font-size:10px"><span>${done?`已完成 ${done}/${p.repeat} 次`:'进度'}</span><span>${num(progress)} / ${p.steps}</span></div><div class="progress gold" style="margin-top:7px"><span style="width:${progress/p.steps*100}%"></span></div><div class="project-meta">启动 ¥${p.cost} · 每次推进另需 ¥60<br>${Object.entries(p.reward).slice(0,3).map(([k,v])=>C.STATS[k][0]+' +'+v).join(' · ')}${done?`<br><span class="quality-label">成果质量 ${num(state.projectQuality[p.id]||0)}/100 · ${byId(C.LOCATIONS,p.location)?.name||'校园空间'}</span>`:''}</div>${active?`<button class="btn soft full" data-action="add" data-id="project" ${E.actionReason(state,'project')?'disabled':''}>${icon('plus','sm')}安排一次推进</button>`:`<button class="btn full" data-action="project" data-id="${p.id}" ${reason?'disabled':''}>${reason?esc(reason):done?'再做一次这个项目':'选择这个项目'}</button>`}</article>`;}
function routesView(){return `<div class="content-heading"><div><h3>不是只有一种优秀</h3><p>同类路线不重复计分。培养专长，再留下一点生活的余地。</p></div><button class="btn compact" data-action="scoring">评分规则</button></div><div class="filters"><button class="filter ${routeTab==='routes'?'active':''}" data-action="route-tab" data-id="routes">${C.ROUTES.length}条成长方向</button><button class="filter ${routeTab==='endings'?'active':''}" data-action="route-tab" data-id="endings">${C.ENDINGS.length}种结局图鉴</button></div>${routeTab==='endings'?endingGrid(false):routeGrid()}`;}
function routeChecklist(r){if(!r.skill)return '';const score=E.routeScores(state)[r.id],done=state.flags[r.proof]||0,work=r.actions.filter(id=>id!=='project').reduce((n,id)=>n+(state.counts[id]||0),0);const rows=[[state.stats[r.skill]>=80,`${C.STATS[r.skill][0]} ${num(state.stats[r.skill])}/80`],[state.stats[r.secondary]>=50,`${C.STATS[r.secondary][0]} ${num(state.stats[r.secondary])}/50`],[done>=(r.id.startsWith('shu_')?2:1),`对应项目 ${done}/${r.id.startsWith('shu_')?2:1}`],[work>=12,`方向行动 ${work}/12`],[score>=80,`成熟度 ${num(score)}/80`]];if(r.id==='socialbiz')rows.push([state.venture.profitableMonths>=3,`盈利 ${state.venture.profitableMonths}/3月`]);return `<div class="route-checklist" aria-label="高阶结局进度">${rows.map(([ok,text])=>`<span class="${ok?'met':''}">${ok?'✓':'○'} ${text}</span>`).join('')}<small>还需完成毕业要求、健康≥45；不要求恋爱。</small></div>`;}
function routeGrid(){const scores=E.routeScores(state,state.phase==='ended');return `<div class="route-grid">${C.ROUTES.map(r=>`<article class="route-card panel"><div class="route-top"><h4>${icon(r.icon)}${r.name}</h4><span class="route-score">${num(scores[r.id])}</span></div><div class="progress ${r.color==='rose'?'rose':r.color==='gold'?'gold':''}"><span style="width:${scores[r.id]}%"></span></div><p class="route-guide">${r.guide}</p>${routeChecklist(r)}<button class="btn compact ${r.id===state.focus?'soft':''}" data-action="focus" data-id="${r.id}" ${state.phase!=='planning'?'disabled':''}>${r.id===state.focus?'正在尝试这个方向':'把它设为当前方向'}</button></article>`).join('')}</div>`;}
function endingGrid(inDialog){const collection=S.collection(),unlocked=collection.endings;return `<div class="row between"><span class="small muted">每次毕业可同时解锁多个结局<br><span class="tiny">结局条件公开；没有必须购买的隐藏内容。</span></span><span class="book-counter">${Object.keys(unlocked).length}<small> / ${C.ENDINGS.length}</small></span></div><div class="endings-grid">${C.ENDINGS.map((e,i)=>`<button class="ending-card ${unlocked[e.id]?'unlocked':''}" data-action="ending-detail" data-id="${e.id}"><div class="row between"><span class="ending-code">NO.${String(i+1).padStart(2,'0')} · ${e.tier}</span>${icon(unlocked[e.id]?'medal':'lock')}</div><h4>${e.title}</h4><p>${e.hint}${!['late_bloom','reset','gaming_drift'].includes(e.id)?'；需完成毕业要求':''}。</p><div class="tiny muted" style="margin-top:8px;font-size:8px">${unlocked[e.id]?`已解锁 · 本机最好 ${num(unlocked[e.id].best)}`:routeName(e.route)+' · 尚未收藏'}</div></button>`).join('')}</div>`;}
function skills(){return `<div class="skills-grid">${Object.keys(C.STATS).map(k=>`<div><div class="row between"><span>${C.STATS[k][0]}</span><span>${num(state.stats[k])}</span></div><div class="progress ${k==='stress'?'rose':''}"><span style="width:${state.stats[k]}%"></span></div></div>`).join('')}</div>`;}
function journalView(){return `<div class="content-heading"><div><h3>留住那些，不只有分数的瞬间</h3><p>月度记录、旅行印章与成长轨迹。空白的地方，仍然等着你。</p></div><button class="btn compact" data-action="export-journal">${icon('down','sm')}导出手帐</button></div><div class="panel panel-pad">${[0,1,2,3].map(y=>`<div class="year-label">${['大一 · 初见','大二 · 探索','大三 · 选择','大四 · 启程'][y]}</div><div class="journal-grid">${Array.from({length:12},(_,i)=>{const m=y*12+i+1,rep=state.reports.find(r=>r.month===m);return `<button class="month-cell ${rep?'done':m===state.month?'current':''}" data-action="month-detail" data-month="${m}" ${!rep?'disabled':''} aria-label="第${m}月记录">${String(m).padStart(2,'0')}</button>`;}).join('')}</div>`).join('')}</div><div class="filters" style="margin-top:17px">${[['memories','人物与回忆'],['places','旅行护照'],['skills','完整属性']].map(([id,label])=>`<button class="filter ${journalTab===id?'active':''}" data-action="journal-tab" data-id="${id}">${label}</button>`).join('')}</div>${journalTab==='places'?`<div class="place-grid">${C.PLACES.map(p=>`<div class="place-stamp ${state.places.includes(p)?'':'locked'}">${icon(state.places.includes(p)?'compass':'lock')}<span>${state.places.includes(p)?p:'等待一场出发'}</span></div>`).join('')}</div>`:journalTab==='skills'?`<section class="panel panel-pad">${skills()}<div class="divider"></div>${academic()}</section>`:state.memories.length?state.memories.slice().reverse().map(m=>`<article class="memory-card"><small>第${m.month}个月</small><h4>${esc(m.title)}</h4><p>${esc(m.text)}</p></article>`).join(''):'<div class="empty">第一段回忆，还在路上。<br>认识一个人，完成一件事，或者去看看新的风景。</div>'}`;}
function renderEnd(){const r=state.result,end=byId(C.ENDINGS,r.primaryEnding),d=r.parts;app.innerHTML=header()+`<main class="graduation"><section class="grad-hero panel"><div class="confetti" aria-hidden="true">${Array.from({length:30},(_,i)=>`<i style="left:${(i*31)%100}%;animation-delay:${i*.035}s"></i>`).join('')}</div><span class="kicker">48 CHAPTERS LATER · THE STORY GOES ON</span><h1>${end.title}</h1><p class="grad-story">${end.story}</p><div class="grad-score">${num(r.rankScore)}</div><p class="grad-subtitle">你的四年 · 综合挑战分<br>原始分 ${num(r.baseScore)} / 10,000　×　个人挑战系数 ${r.multiplier.toFixed(2)}<br>所有故事都发生在上海大学；挑战系数来自个人难度，而不是学校排名。</p><div class="grad-tags"><span class="tag">${esc(state.profile.name)} · ${byId(C.SCHOOLS,state.profile.school).name}</span><span class="tag ${r.graduated?'gold':'rose'}">${r.graduated?'毕业要求已完成':'仍有毕业要求待补齐'}</span><span class="tag neutral">本局解锁 ${r.endings.length} 个结局</span><span class="tag">上大手帐 ${state.shu.completed.length}/12 页</span></div><div class="grad-actions"><button class="btn primary" data-action="export-journal">${icon('down','sm')}带走毕业手帐</button><button class="btn" data-action="saves">保存这一段故事</button><button class="btn" data-action="leaderboard">${icon('trophy','sm')}看看本机榜单</button><button class="btn soft" data-action="new-run">再过一种四年</button></div></section><div class="grad-content"><section class="panel grad-panel"><h3>分数背后，是你走过的路</h3><p>强项得到主要奖励，副方向与生活得到额外加分。</p>${scoreBreakdown(r)}<div class="notice green small">最成熟的方向：${r.rankedRoutes.slice(0,3).map(x=>routeName(x.id)+' '+num(x.score)).join(' ／ ')}。同类升学与同类恋爱不重复叠分。</div><div class="grad-stat-grid"><div class="grad-stat"><strong>${num(r.gradeAverage)}</strong><span>累计学期均分</span></div><div class="grad-stat"><strong>${r.uniqueActions}</strong><span>尝试过的行动</span></div><div class="grad-stat"><strong>${r.places}</strong><span>旅行记忆</span></div></div><button class="btn compact" style="margin-top:18px" data-action="stats">查看完整属性与成绩</button></section><section class="panel grad-panel"><h3>一生不止一个标签</h3><p>本次满足条件的结局，已收进本机图鉴。</p><div class="grad-unlocked">${r.endings.map(id=>{const e=byId(C.ENDINGS,id);return `<button class="grad-ending-button" data-action="ending-detail" data-id="${id}">${icon(e.tier==='S'?'medal':'book')}<span>${e.title}</span><span class="tag ${e.tier==='S'?'gold':'neutral'}" style="margin-left:auto">${e.tier}</span></button>`;}).join('')}</div>${r.partner?`<div class="divider"></div><div class="row">${A.portrait(E.npcs[r.partner.id],54)}<div><h4 class="small">与你一起翻页的人：${esc(r.partner.name)}</h4><p class="tiny muted">在一起 ${r.partner.months}个月 · 共同回忆 ${r.partner.memories}<br>信任 ${num(r.partner.trust)} · 亲近度 ${num(r.partner.affection)}</p></div></div>`:''}<div class="divider"></div><p class="tiny muted">没有连接服务器时，排行榜仅属于本机浏览器。<br>导出存档和图鉴备份，可以把这份记录带走。</p></section></div><div class="panel grad-panel" style="margin-top:18px"><div class="row between"><h3>最后，再看一眼这四年</h3><button class="btn compact" data-action="replay-export">导出可复现回放</button></div><div class="grad-content" style="margin-top:0">${state.memories.slice(-6).map(m=>`<article class="memory-card"><small>第${m.month}个月</small><h4>${esc(m.title)}</h4><p>${esc(m.text)}</p></article>`).join('')||'<p class="small muted">你自己的记忆，不必每一件都被系统记录。</p>'}</div></div></main>`+footer();}
function scoreBreakdown(r){return `<div class="score-list">${[['specialty','最强专长',7000],['secondary','其他两类方向',1500],['life','生活状态',1000],['experience','探索与关系',500]].map(([k,label,max])=>`<div class="score-line"><span>${label}</span><div class="progress ${k==='life'?'rose':k==='experience'?'gold':''}"><span style="width:${r.parts[k]/max*100}%"></span></div><strong>${num(r.parts[k])}</strong></div>`).join('')}${r.graduationPenalty?`<div class="score-line"><span>毕业要求未满足</span><span class="tiny muted">原始总分扣减18%</span><strong class="error">-${num(r.graduationPenalty)}</strong></div>`:''}</div>`;}
function render(){if(disposed)return;if(modalLocked&&(!state||!['events','report'].includes(state.phase)))closeModal(true);if(!state)renderStart();else if(state.phase==='ended')renderEnd();else renderGame();if(state?.phase==='events')showEvent();else if(state?.phase==='report')showReport(state.reports.at(-1),true);}
let confirmCallback=null;
function showModal(title,body,{kicker='',wide=false,locked=false,kind='general'}={}){activeDialog=kind;modalLocked=locked;dialog.className=wide?'wide':'';dialog.innerHTML=`<div class="dialog-head"><div>${kicker?`<span class="kicker">${esc(kicker)}</span>`:''}<h2 id="dialog-title" tabindex="-1">${title}</h2></div>${locked?'':`<button class="icon-button" data-action="close-modal" aria-label="关闭">${icon('cross')}</button>`}</div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;requestAnimationFrame(()=>{if(dialog.open){const el=dialog.querySelector('[autofocus]')||dialog.querySelector('#dialog-title');el?.focus({preventScroll:true});}});}
function closeModal(force=false){if(modalLocked&&!force)return;dialog.close();activeDialog='';modalLocked=false;confirmCallback=null;}
function confirmBox(title,text,label,callback){confirmCallback=callback;showModal(title,`<p>${esc(text)}</p><div class="row" style="justify-content:flex-end"><button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="confirm-yes">${esc(label)}</button></div>`,{kind:'confirm'});}
function choiceMeta(o){const parts=[];if(o.cost)parts.push('支出 ¥'+o.cost);if(o.money)parts.push('获得 ¥'+o.money);for(const[k,v]of Object.entries(o.stats||{}))if(C.STATS[k])parts.push(C.STATS[k][0]+fmtDelta(v));if(o.effect==='arc')parts.push('信任 +'+o.trust);if(o.check)parts.push('结果取决于能力与轻微随机波动');return parts.join(' · ');}
function showEvent(){const e=E.currentEvent(state);if(!e)return;const q=state.pending.length;showModal(esc(e.title),`<div class="event-paper">${e.npc?`<div class="event-avatar">${A.portrait(E.npcs[e.npc],45)}</div>`:''}<div class="event-kicker">${icon(e.npc?'heart':'pen')}<span>第${state.month}个月 · 生活给你出了一道小题</span></div><p class="event-text">${esc(e.text)}</p><div class="choices">${e.options.map((o,i)=>{const reason=E.optionReason(state,o);return `<button class="choice" data-action="event-choice" data-index="${i}" ${reason?'disabled':''}><span class="choice-number">${String.fromCharCode(65+i)}</span><span class="choice-content">${esc(o.label)}${choiceMeta(o)?`<span class="choice-meta" style="display:block">${esc(choiceMeta(o))}</span>`:''}${reason?`<span class="choice-reason" style="display:block">${esc(reason)}</span>`:''}</span></button>`;}).join('')}</div><div class="event-footer"><span>当前余额 ¥${num(state.money)}</span><span>本月还有 ${q} 则事件 · 选择后自动保存</span></div></div>`,{kicker:'A MOMENT TO REMEMBER',locked:true,kind:'event'});}
function showReport(report,advance=false){if(!report)return;const changes=Object.entries(report.delta).filter(([k,v])=>Math.abs(v)>=.5).sort((a,b)=>Math.abs(b[1])-Math.abs(a[1])).slice(0,12);const positive=changes.filter(([k,v])=>k==='stress'?v<0:v>0).length;showModal(`第${report.month}个月，已收藏。`,`<div class="report-summary"><div class="report-chip"><span>行动完成</span><strong>4 / 4</strong></div><div class="report-chip"><span>月度结余变化</span><strong>${fmtDelta(report.moneyDelta)}</strong></div><div class="report-chip"><span>${[5,10].includes(((report.month-1)%12)+1)?'累计学期均分':'成长变化'}</span><strong>${[5,10].includes(((report.month-1)%12)+1)?num(report.grade):positive+'项'}</strong></div></div><div class="delta-list">${changes.map(([k,v])=>`<span class="delta-tag ${(k==='stress'?v>0:v<0)?'negative':''}">${C.STATS[k][0]} ${fmtDelta(v)}</span>`).join('')}</div><div class="log-list">${report.log.map(x=>`<p class="log-entry ${x.type}">${esc(x.text)}</p>`).join('')}</div>${advance?`<button class="btn primary full" data-action="next-month" id="next-month">翻到第${state.month+1}个月 ${icon('arrow')}</button><p class="status-line">本月记录已保存。关闭页面后，也可从这里继续。</p>`:''}`,{kicker:'YOUR MONTHLY SCRAPBOOK',locked:advance,kind:advance?'report':'past-report'});}
function showSaves(){const slots=S.slots();showModal('把故事妥善收好',`<p>自动存档记录当前进度。三个手动存档位可留在不同的人生岔路口。文件备份也可以跨设备带走。</p><div class="save-grid">${slots.map(s=>`<div class="save-row"><div><h4>${s.id==='auto'?'自动存档':'手动存档 '+s.id}${s.exists?' · '+esc(s.name):''}</h4><p>${s.exists?`第${s.month}月 · ${s.phase==='ended'?'已经毕业':s.phase==='events'?'正在经历事件':s.phase==='report'?'月度报告':'月度安排'}`:'还没有写下故事'}</p></div><div class="save-actions">${s.id!=='auto'?`<button class="btn compact" data-action="save-slot" data-id="${s.id}" ${!state?'disabled':''}>保存</button>`:''}<button class="btn compact" data-action="load-slot" data-id="${s.id}" ${!s.exists?'disabled':''}>读取</button></div></div>`).join('')}</div><div class="file-actions"><button class="btn" data-action="export-save" ${!state?'disabled':''}>${icon('down','sm')}导出当前存档</button><button class="btn" data-action="import-save">${icon('up','sm')}导入存档文件</button><button class="btn" data-action="export-book">备份图鉴与本机榜</button><button class="btn" data-action="import-book">合并图鉴备份</button></div><p class="status-line ${S.status().durable?'':'error'}">${esc(status())}${S.status().error?' · '+esc(S.status().error):''}</p><div class="cloud-controls"><div class="row between"><span class="cloud-status">${B.connected()?'可选云同步已连接；只在你点击时传输。':'云同步未启用。纯单机功能无需后端。'}</span></div><div class="row wrap" style="margin-top:10px"><button class="btn compact" data-action="cloud-save" ${!state||!B.connected()?'disabled':''}>上传当前进度</button><button class="btn compact" data-action="cloud-load" ${!B.connected()?'disabled':''}>读取云进度</button></div><p class="status-line">云端版本冲突不会覆盖任一存档。先导出本地备份，再决定采用哪个版本。</p></div>`,{kind:'saves'});}
function showHelp(){showModal('第一次翻开这四年？',`<div class="help-step"><span>1</span><div><h4>一个月，安排四件事</h4><p>每项行动占一个时段；可以重新排序。先工作赚到的钱，可供后面的行动使用。同一行动每月最多两次。</p></div></div><div class="help-step"><span>2</span><div><h4>选择一个方向，但不用被它困住</h4><p>图书馆、恋爱、创业、运动、游戏、旅行都能成长。方向分高不等于结局已解锁；常常还需要做完项目或参加关键申请。</p></div></div><div class="help-step"><span>3</span><div><h4>让属性之间发生化学反应</h4><p>思考力提高学习效率，户外活动反哺备考。外貌提高好感增长与主动追求概率，信任来自相处。正规电竞训练比通宵更可持续。</p></div></div><div class="help-step"><span>4</span><div><h4>记住几个重要的月份</h4><p>每学年的第5、10月结算学期成绩；36月推免申请、37月推免结果与毕业设计开放、38月考研报名、40月初试、43月复试。39月其他申请、44月结果。</p></div></div><div class="help-step"><span>5</span><div><h4>所有路线都要记得毕业</h4><p>完成毕业设计、无待补课程、均分至少60。没做完也会获得完整结局，但原始总分扣18%。你不会因为某一次失败被强行结束游戏。</p></div></div><div class="help-step"><span>6</span><div><h4>技能、课程与社团，一起成长</h4><p>技能树有40项技能，最多装备3项；只掌握、不装备不会加成。每个长学期选一门专题课，完成匹配行动才有奖励。社团贡献要持续投入，朋友也能成为项目合作者。</p></div></div><div class="help-step"><span>7</span><div><h4>用成果证明能力，用现金流支撑创业</h4><p>新方向没有对应成果时，成熟度最高55。高阶结局还要求真实方向投入、能力和毕业资格；创业高阶结局要求至少3个盈利月份。上课、活动、作品和关系不能只留在属性栏里。</p></div></div><div class="notice green">新手示例：上课／技能 → 一次兴趣或社交 → 一次项目 → 一次休息或运动。需要赚钱时，先插入勤工助学。不要连续48个月只按同一套方案。</div><div class="divider"></div><p>本版本只有上海大学校园。个人挑战改变游戏成长和评分系数，不改变学校身份；所有能力、升学门槛和48月进程都是玩法抽象，不是现实培养方案。上大手帐连接原有全部路线，不要求任务全部完成。</p><button class="btn compact" data-action="scoring">查看完整计分方式</button>`,{kind:'help'});}
function showScoring(){showModal('每一种认真，都有自己的高分',`<p>所有路线先换算为0—100的成熟度，再从不同类别里挑出最好的三条。保研／考研／海外升学不重复叠加；普通恋爱与富有伴侣路线也不重复叠加。</p><div class="help-step"><span>70</span><div><h4>最强专长：最多7000分</h4><p>最高方向成熟度 ×70。先把自己喜欢的一条路线做深，就有机会拿到很高的基础分。</p></div></div><div class="help-step"><span>15</span><div><h4>其他两类方向：最多1500分</h4><p>不同类别中的第二、第三名，各自成熟度 ×7.5。不是把${C.ROUTES.length}条路线全部加起来。</p></div></div><div class="help-step"><span>10</span><div><h4>生活状态：最多1000分</h4><p>健康40%＋幸福感40%＋低压力20%，再乘10。长时间透支会反映在分数里。</p></div></div><div class="help-step"><span>5</span><div><h4>探索与关系：最多500分</h4><p>体验过的行动类型、旅行记忆与有信任基础的朋友共同决定。不同维度均设上限。</p></div></div><div class="notice">原始分上限10,000。毕业要求未完成扣原始分18%。挑战分＝原始分×个人挑战系数（1.00／1.04／1.09／1.14）。系数是游戏平衡参数，不是现实价值判断。</div><p class="status-line">新方向在没有对应项目成果时，成熟度封顶55；完成后的成果质量进入评分。达到高阶结局还需足够能力、至少12次对应行动和毕业要求；创业及社会企业高阶结局另需3个盈利月份。毕业时可以同时解锁多个结局。主结局按已达成结局的成熟度、等级与当前方向选择；切换目标不会凭空增加分数。</p>`,{kind:'scoring'});}
function showStats(){if(!state){toast('先开始一段故事，再查看人物成长。');return;}const r=byId(C.ROUTES,state.focus);showModal(`${esc(state.profile.name)}的成长档案`,`<div class="row between"><span class="tag">${byId(C.SCHOOLS,state.profile.school).name} · 第${state.month}月</span><span class="finance-main" style="font-size:22px">¥${num(state.money)}</span></div>${state.phase==='planning'?`<label style="margin-top:15px"><span class="field-label">当前尝试方向</span><select data-action-select="focus-modal">${C.ROUTES.map(x=>`<option value="${x.id}" ${x.id===state.focus?'selected':''}>${x.name}</option>`).join('')}</select></label>`:''}<p class="status-line">${r.guide}</p>${skills()}<div class="divider"></div>${academic()}${state.grades.length?`<h3>学期记录</h3><div class="delta-list">${state.grades.map(g=>`<span class="delta-tag ${g.grade<60?'negative':''}">第${g.month}月：${g.grade}</span>`).join('')}</div>`:''}<p class="status-line">挑战种子：${esc(state.seed)}。同一种子与相同选择可复现本局；不会读取系统位置、通讯录或个人数据。</p>`,{kind:'stats'});}
function showNpc(id){const n=E.npcs[id],r=state.relations[id];showModal(`${n.name} · 慢慢认识`,`${A.portrait(n,80)}<p style="margin-top:16px">${n.intro}</p><div class="notice green">喜欢：${n.like}<br>相处偏好参考：${C.STATS[n.affinity][0]}。喜好会影响好感增长，而不是决定对方的全部。</div><p class="status-line">亲近度${num(r.affection)}，信任${num(r.trust)}。${E.romanceAllowed(state,id)?`当前理论表白成功率${E.confessionChance(state,id)}%；实际仍需亲近55、信任25、双方单身及冷却期结束。`:'当前恋爱偏好不包含该角色，可以发展深厚友情。'}</p><h3>你们一起打开的故事</h3>${n.chapters.map((ch,i)=>`<div class="memory-card"><small>第${i+1}章 · ${i<r.chapter?'已经历':'尚未经历'}</small><h4>${ch[0]}</h4><p>${i<r.chapter?ch[1]:`亲近度达到${[25,55,80][i]}、信任达到${[12,30,55][i]}后可能触发；两章至少间隔3月。`}</p></div>`).join('')}<div class="row wrap" style="margin-top:17px"><button class="btn soft" data-action="npc-add" data-id="listen" data-target="${id}">安排一次认真聊天</button><button class="btn" data-action="npc-select" data-id="${id}">设为互动对象</button></div>`,{kind:'npc'});}
function showBook(){showModal('每一条路，都值得被收藏',endingGrid(true),{kicker:'THE ENDING COLLECTION',wide:true,kind:'book'});}
function showEnding(id){const e=byId(C.ENDINGS,id);if(!e)return;const entry=S.collection().endings[id],current=state?.result?.endings.includes(id);showModal(e.title,`<div class="row wrap"><span class="tag ${e.tier==='S'?'gold':'neutral'}">${e.tier}级结局</span><span class="tag">${routeName(e.route)}</span><span class="tag neutral">${entry||current?'已收藏':'尚未解锁'}</span></div><p class="event-text" style="margin-top:20px">${e.story}</p><div class="notice green">达成条件：${e.hint}${!['late_bloom','reset','gaming_drift'].includes(e.id)?'；完成毕业设计、无待补课程、均分至少60':''}。</div><p class="status-line">${byId(C.ROUTES,e.route).guide}</p>${entry?`<p class="status-line">本机最好成绩 ${num(entry.best)}，共收藏 ${entry.count}次。</p>`:''}<button class="btn compact" data-action="book" style="margin-top:14px">回到完整图鉴</button>`,{kicker:'ANOTHER WAY TO LIVE',kind:'ending'});}
function leaderboardHTML(){const rows=leaderboardRows.filter(r=>!leaderboardSchool||r.difficulty===leaderboardSchool);return `<div class="leaderboard-source"><button class="filter ${leaderboardSource==='local'?'active':''}" data-action="leaderboard-source" data-id="local">本机榜单</button><button class="filter ${leaderboardSource==='online'?'active':''}" data-action="leaderboard-source" data-id="online" ${!B.connected()?'disabled':''}>联网榜单</button></div><label class="row between"><span class="small muted">按个人挑战查看</span><select data-action-select="leaderboard-school" style="width:145px;min-height:33px;font-size:11px;padding:6px 9px"><option value="">全部挑战</option>${C.DIFFICULTIES.map(s=>`<option value="${s.id}" ${leaderboardSchool===s.id?'selected':''}>${s.name}</option>`).join('')}</select></label>${leaderboardError?`<p class="status-line error">${esc(leaderboardError)}</p>`:''}${networkBusy?'<div class="empty">正在读取榜单……</div>':rows.length?`<table class="leaderboard-table"><thead><tr><th>名次</th><th>同学与结局</th><th>挑战</th><th>挑战分</th></tr></thead><tbody>${rows.slice(0,30).map((r,i)=>`<tr><td>${String(i+1).padStart(2,'0')}</td><td>${esc(r.name)}<br><span class="tiny muted">${esc(byId(C.ENDINGS,r.primaryEnding)?.title||'毕业故事')}</span></td><td>${esc(byId(C.DIFFICULTIES,r.difficulty)?.mark||'上大')}<br><span class="tiny muted">${r.verified?'规则回放通过':'本地记录'}</span></td><td><strong>${num(r.rankScore)}</strong></td></tr>`).join('')}</tbody></table>`:'<div class="empty">这里还没有毕业记录。<br>你的第一段故事，可以从空白开始。</div>'}<div class="notice green">${leaderboardSource==='local'?'这里只展示当前浏览器真正完成过的记录，没有虚构对手。换浏览器不会自动带走成绩，请备份图鉴。':'联网成绩需要后端校验。示例服务会回放完整选择历史重算分数；回放通过不等于验证真人操作。'}</div>${state?.phase==='ended'?`<button class="btn primary full" style="margin-top:15px" data-action="submit-score" ${!B.connected()||networkBusy?'disabled':''}>提交本局到联网榜单</button><p class="status-line">手动提交会发送角色昵称、结算结果、游戏种子和选择回放，不发送本机其他存档。</p>`:''}`;}
function showLeaderboard(){leaderboardRows=leaderboardSource==='local'?S.leaderboard():leaderboardRows;showModal('给每一种四年，留一个位置',leaderboardHTML(),{kicker:'SCOREBOARD · REAL SAVED RUNS ONLY',kind:'leaderboard'});}
async function refreshOnline(){networkBusy=true;leaderboardError='';showLeaderboard();try{const result=await B.fetchLeaderboard({difficulty:leaderboardSchool,limit:30});const rows=Array.isArray(result)?result:result.items;if(!Array.isArray(rows))throw new Error('榜单接口未返回items数组');leaderboardRows=rows.filter(r=>r&&typeof r.name==='string'&&Number.isFinite(r.rankScore)&&r.rankScore>=0&&r.rankScore<=11400).sort((a,b)=>b.rankScore-a.rankScore);}catch(e){leaderboardError=e.message;leaderboardRows=[];}finally{networkBusy=false;if(activeDialog==='leaderboard')showLeaderboard();}}
function download(name,text,type='application/json'){const blob=new Blob([text],{type:type+';charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportJournal(){if(!state)return;const r=state.result;let text=`# ${config.title}：${state.profile.name}的成长手帐\n\n游戏版本：${C.VERSION} / ${C.RULES_VERSION}\n起点：${byId(C.SCHOOLS,state.profile.school).name}\n挑战种子：${state.seed}\n个人挑战：${E.difficulty(state).name}\n上大手帐：${state.shu.completed.length}/12 页\n记录月份：${state.month}/48\n\n`;if(r){text+=`## 毕业结算\n\n主结局：${byId(C.ENDINGS,r.primaryEnding).title}\n挑战分：${r.rankScore}；原始分：${r.baseScore}/10000；个人挑战系数：${r.multiplier}\n毕业要求：${r.graduated?'已完成':'尚未完成'}\n累计均分：${r.gradeAverage}\n\n${byId(C.ENDINGS,r.primaryEnding).story}\n\n### 本次解锁\n\n${r.endings.map(id=>'- '+byId(C.ENDINGS,id).title).join('\n')}\n\n`;}
 text+='## 成长属性\n\n'+Object.entries(state.stats).map(([k,v])=>`- ${C.STATS[k][0]}：${v}`).join('\n')+'\n\n## 相遇与记忆\n\n'+state.memories.map(m=>`### 第${m.month}月 · ${m.title}\n\n${m.text}\n`).join('\n')+'\n## 月度安排与事件\n\n'+state.reports.map(m=>`### 第${m.month}月\n\n安排：${m.plan.map(x=>E.actions[x.id].name+(x.target?'（'+E.npcs[x.target].name+'）':'')).join(' → ')}\n\n${m.log.map(x=>'- '+x.text).join('\n')}\n`).join('\n')+'\n\n---\n本手帐记录虚构游戏人生，不是现实招生、心理或职业评估。\n';download(`未完的四年-${state.profile.name}-第${state.month}月手帐.md`,text,'text/markdown');}
function fillPlan(){if(!state||state.phase!=='planning')return;const route=byId(C.ROUTES,state.focus);let started='';if(!state.activeProject){const choice=state.month>=37&&!state.flags.thesis?'thesis':route.proof?C.PROJECTS.find(p=>p.flag===route.proof&&!(state.flags[route.proof]>0))?.id:null;if(choice&&!E.projectReason(state,choice)){const r=E.chooseProject(state,choice);if(r.ok)started=E.projects[choice].name;}}const urgent=state.recovery||state.stats.health<45||state.stats.stress>65,ids=[...(urgent?['rest','run']:[]),...(state.activeProject?['project']:[]),...(state.venture.mode!=='off'?['clienttalk']:[]),...route.actions,'rest','lecture','parttime','run','home'];let guard=0;while(state.plan.length<4&&guard++<4){let added=false;for(const id of ids){if(state.plan.some(x=>x.id===id)&&state.plan.length<3)continue;const a=E.actions[id],res=E.queueAction(state,id,a?.target?target:undefined);if(res.ok){added=true;break;}}if(!added)break;}afterChange('planning');toast(started?'已启动「'+started+'」并补齐安排；可继续调整。':'已按目标补齐；这是建议，不会自动保证高阶结局。');}
function addAction(id,npc){const a=E.actions[id];if(!state||!a)return;if(a.target)target=npc||target;const old=state.phase,out=E.queueAction(state,id,a.target?target:undefined);if(!out.ok){toast(out.reason);return;}if(activeDialog==='npc')closeModal();afterChange(old);chime();toast(`已安排「${a.name}」 · ${state.plan.length}/4`);}
let importKind='save';
function requestImport(kind){importKind=kind;$('#import-file').value='';$('#import-file').click();}
function rerenderStartKeepingDetails(){const expanded=!!document.querySelector('.talent-detail[open]');renderStart();if(expanded)document.querySelector('.talent-detail')?.setAttribute('open','');}
async function clickHandler(ev){const button=ev.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action,id=button.dataset.id,idx=Number(button.dataset.index),npc=button.dataset.target;
 switch(action){
  case'map-area':mapArea=id;renderGame();break;
  case'map-place':view='actions';category='all';locationFilter=id;actionSearch='';renderGame();break;
  case'clear-location':locationFilter='';renderGame();break;
  case'search-actions':{actionSearch=$('[data-action-select="search-action"]')?.value.trim()||'';category='all';renderGame();break;}
  case'unlock-skill':if(applyEngine(()=>E.unlockSkill(state,id)))toast('已掌握技能；装备后才会获得成长加成。');break;
  case'equip-skill':applyEngine(()=>E.equipSkill(state,id));break;
  case'join-club':applyEngine(()=>E.joinClub(state,id));break;
  case'select-course':applyEngine(()=>E.selectCourse(state,id));break;
  case'dorm-pact':applyEngine(()=>E.setDormPact(state,id));break;
  case'venture-mode':applyEngine(()=>E.setVentureMode(state,id));break;
  case'sources':showSources();break;
  case'home':if(state){save();state=null;closeModal(true);renderStart();}else root.scrollTo({top:0,behavior:'smooth'});break;
  case'difficulty':setup.difficulty=id;rerenderStartKeepingDetails();break;
  case'shu-chapter':shuChapter=Number(id);view='shu';renderGame();break;
  case'talent':if(setup.talents.includes(id))setup.talents=setup.talents.filter(x=>x!==id);else if(setup.talents.length<2)setup.talents.push(id);else{toast('先取消一项天赋，再选择新的。');break;}rerenderStartKeepingDetails();break;
  case'start':beginRun();break;
  case'continue':load('auto');break;
  case'new-run':closeModal(true);state=null;renderStart();root.scrollTo({top:0,behavior:'instant'});break;
  case'tab':view=id;renderGame();break;
  case'filter':category=id;locationFilter='';renderGame();break;
  case'route-tab':routeTab=id;renderGame();break;
  case'journal-tab':journalTab=id;renderGame();break;
  case'add':addAction(id);break;
  case'npc-add':addAction(id,npc);break;
  case'npc-select':target=id;closeModal();view='people';render();toast('互动对象已设为'+E.npcs[id].name);break;
  case'remove':applyEngine(()=>E.removeAction(state,idx));break;
  case'up':E.moveAction(state,idx,-1);afterChange(state.phase);break;
  case'down':E.moveAction(state,idx,1);afterChange(state.phase);break;
  case'clear-plan':state.plan=[];afterChange(state.phase);break;
  case'copy-plan':{state.plan=[];for(const p of lastPlan)E.queueAction(state,p.id,p.target);afterChange(state.phase);toast(state.plan.length===4?'已沿用上月安排。':'部分行动暂不可用，已保留能执行的项目。');break;}
  case'fill-plan':fillPlan();break;
  case'resolve':{if(!state||state.phase!=='planning')break;lastPlan=E.clone(state.plan);const okay=applyEngine(()=>E.resolveMonth(state));if(okay)chime();break;}
  case'event-choice':applyEngine(()=>E.chooseOption(state,idx));break;
  case'next-month':closeModal(true);applyEngine(()=>E.nextMonth(state));root.scrollTo({top:0,behavior:'instant'});break;
  case'project':{const success=applyEngine(()=>E.chooseProject(state,id));if(success)toast('已选择项目，请安排「推进长期项目」投入时段。');break;}
  case'focus':applyEngine(()=>E.changeFocus(state,id));break;
  case'help':showHelp();break;
  case'scoring':showScoring();break;
  case'book':showBook();break;
  case'stats':showStats();break;
  case'npc-detail':showNpc(id);break;
  case'ending-detail':showEnding(id);break;
  case'month-detail':showReport(state.reports.find(r=>r.month===Number(button.dataset.month)),false);break;
  case'saves':showSaves();break;
  case'save-slot':{const old=S.slots().find(x=>x.id===id);const doit=()=>{save(id);showSaves();toast('已保存到手动存档'+id);};if(old?.exists)confirmBox('覆盖手动存档？',`手动存档${id}中是${old.name}的第${old.month}月。自动存档和其他存档位不受影响。`,'确认覆盖',doit);else doit();break;}
  case'load-slot':confirmBox('读取这份故事？','读取会替换当前自动存档。当前进度已自动保存；需要保留两条分支时，请先保存到另一个手动槽位或导出文件。','读取存档',()=>load(id));break;
  case'export-save':if(state)download(`未完的四年-${state.profile.name}-第${state.month}月.json`,JSON.stringify(S.envelope(state),null,2));break;
  case'import-save':requestImport('save');break;
  case'export-book':download('未完的四年-图鉴与本机榜单.json',JSON.stringify(S.exportCollection(),null,2));break;
  case'import-book':requestImport('book');break;
  case'export-journal':exportJournal();break;
  case'replay-export':if(state)download('未完的四年-可复现回放.json',JSON.stringify({rulesVersion:C.RULES_VERSION,history:state.history},null,2));break;
  case'breakup-confirm':confirmBox('坦诚结束这段关系？','这会占用一个行动时段。关系结束后，你们仍可保持朋友关系。','安排一次告别',()=>{closeModal(true);addAction('breakup',npc);});break;
  case'leaderboard':leaderboardSource='local';leaderboardError='';showLeaderboard();break;
  case'leaderboard-source':leaderboardSource=id;leaderboardError='';if(id==='online')await refreshOnline();else showLeaderboard();break;
  case'submit-score':if(networkBusy)break;confirmBox('提交这段游戏人生？','将发送角色昵称、结算结果、游戏种子和本局选择回放，用于后端重算成绩。不会发送其他存档。','提交本局',async()=>{networkBusy=true;leaderboardSource='online';showLeaderboard();try{await B.submitScore();toast('本局成绩已提交。');await refreshOnline();}catch(e){leaderboardError=e.message;networkBusy=false;showLeaderboard();}});break;
  case'cloud-save':if(networkBusy)break;networkBusy=true;try{await B.syncProgress();toast('当前进度已同步到云端。');}catch(e){toast(e.status===409?'云端存在新版本，未覆盖。请先导出本地备份，再读取云进度。':e.message);}finally{networkBusy=false;}break;
  case'cloud-load':confirmBox('读取云端进度？','这会替换当前自动存档。建议先导出本地版本，避免丢失不同设备上的分支。','读取云端',async()=>{try{const out=await B.loadProgress();if(out)toast('云端进度已载入。');else{showSaves();toast('云端还没有存档。');}}catch(e){showSaves();toast(e.message);}});break;
  case'sound':sound=!sound;if(sound)chime();toast(sound?'已开启轻音效。':'已关闭音效。');if(state)render();else renderStart();break;
  case'close-modal':closeModal();break;
  case'confirm-yes':{const cb=confirmCallback;confirmCallback=null;closeModal(true);if(cb)await cb();break;}
 }
}
function changeHandler(ev){const el=ev.target;if(el.dataset.setup){setup[el.dataset.setup]=el.value;return;}const type=el.dataset.actionSelect;if(type==='collaborator'){applyEngine(()=>E.setCollaborator(state,el.value));return;}if(type==='search-action'){actionSearch=el.value.trim();return;}if(type==='focus'||type==='focus-modal'){const wasModal=type==='focus-modal';applyEngine(()=>E.changeFocus(state,el.value));if(wasModal)showStats();}if(type==='target'){target=el.value;renderGame();}if(type==='leaderboard-school'){leaderboardSchool=el.value;if(leaderboardSource==='online')refreshOnline();else showLeaderboard();}}
function searchKeyHandler(ev){if(ev.key==='Enter'&&ev.target.dataset.actionSelect==='search-action'){ev.preventDefault();actionSearch=ev.target.value.trim();category='all';renderGame();}}
function inputHandler(ev){if(ev.target.dataset.setup)setup[ev.target.dataset.setup]=ev.target.value;}
async function fileHandler(ev){const file=ev.target.files?.[0];if(!file)return;if(file.size>1500000){toast('文件过大；存档或图鉴文件应小于1.5MB。');return;}try{const text=await file.text();if(importKind==='save'){const imported=S.fromText(text);confirmBox('导入新的游戏存档？',`将载入${imported.profile.name}的第${imported.month}个月，并替换自动存档。手动存档与图鉴仍然保留。`,'确认导入',()=>{replaceState(imported);toast('存档已导入。');});}else{const parsed=JSON.parse(text);S.importCollection(parsed);showBook();toast('图鉴已合并，本地已有记录保留。');}}catch(e){toast('导入失败：'+e.message);}}
function cancelHandler(e){if(modalLocked){e.preventDefault();return;}activeDialog='';confirmCallback=null;}
function pageHide(){if(state)try{save();}catch(e){/* Avoid claiming persistence if browser is closing. */}}
function visibility(){if(document.hidden&&audio?.state==='running')audio.suspend();}
B._bind({getState:()=>state,replaceState,save,load,destroy:()=>{disposed=true;document.removeEventListener('click',clickHandler);document.removeEventListener('change',changeHandler);document.removeEventListener('input',inputHandler);document.removeEventListener('keydown',searchKeyHandler);$('#import-file').removeEventListener('change',fileHandler);dialog.removeEventListener('cancel',cancelHandler);root.removeEventListener('pagehide',pageHide);document.removeEventListener('visibilitychange',visibility);clearTimeout(toastTimer);audio?.close();if(dialog.open)dialog.close();app.innerHTML='';}});
document.addEventListener('click',clickHandler);document.addEventListener('change',changeHandler);document.addEventListener('input',inputHandler);document.addEventListener('keydown',searchKeyHandler);$('#import-file').addEventListener('change',fileHandler);dialog.addEventListener('cancel',cancelHandler);root.addEventListener('pagehide',pageHide);document.addEventListener('visibilitychange',visibility);
renderStart();B._emit('ready',{version:C.VERSION,rulesVersion:C.RULES_VERSION,features:{offline:true,manualSlots:3,months:48,endings:C.ENDINGS.length,npcs:C.NPCS.length,projects:C.PROJECTS.length},storage:S.status()});
})(window);
